<?php
declare(strict_types=1); require_once __DIR__.'/../../config/config.php'; app_boot(); $userId=require_auth(); $action=$_GET['action']??$_POST['action']??''; $pdo=db();
if($action==='list'){ $st=$pdo->prepare('SELECT media_id id,type,current_seconds current,duration,UNIX_TIMESTAMP(updated_at)*1000 updatedAt FROM history WHERE user_id=? ORDER BY updated_at DESC LIMIT 100');$st->execute([$userId]);json_response(true,'History',$st->fetchAll()); }
if($action==='save'){ require_method('POST');$d=request_json();$mid=(int)($d['mediaId']??0);$type=$d['type']??'audio';$cur=max(0,(float)($d['current']??0));$dur=max(0,(float)($d['duration']??0));if(!$mid)json_response(false,'Invalid media id.',null,422);$st=$pdo->prepare('INSERT INTO history(user_id,media_id,type,current_seconds,duration) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE type=VALUES(type),current_seconds=VALUES(current_seconds),duration=VALUES(duration),updated_at=CURRENT_TIMESTAMP');$st->execute([$userId,$mid,$type,$cur,$dur]);json_response(true,'History saved'); }
if($action==='clear'){ require_method('POST');$d=request_json();if(isset($d['mediaId']))$pdo->prepare('DELETE FROM history WHERE user_id=? AND media_id=?')->execute([$userId,(int)$d['mediaId']]);else$pdo->prepare('DELETE FROM history WHERE user_id=?')->execute([$userId]);json_response(true,'History cleared'); }
json_response(false,'Unknown history action.',null,400);
